// Package stdlib holds DBTX, the interface that repositories generated by kanna-orm for database/sql run on. Each
// generated package declares its DBTX as this one, so a single value serves all of them, as when a dependency injector
// provides it once.
package stdlib

import (
	"context"
	"database/sql"
)

// DBTX is what repositories run on: *sql.DB, *sql.Conn, or *sql.Tx. If you wrap a transaction in your own
// DBTX, give it an `Unwrap() DBTX` method that returns the transaction, so that methods that lock rows can tell they
// run inside one.
type DBTX interface {
	ExecContext(ctx context.Context, query string, args ...any) (sql.Result, error)
	QueryContext(ctx context.Context, query string, args ...any) (*sql.Rows, error)
	QueryRowContext(ctx context.Context, query string, args ...any) *sql.Row
}
